DO $$
DECLARE manager uuid; member uuid; account_user uuid; outsider uuid; new_user uuid;
 org bigint; unit_id bigint; event_id bigint; draft_id uuid:=gen_random_uuid(); response jsonb;
 token1 text:=repeat('1',64); token2 text:=repeat('2',64); token3 text:=repeat('3',64);
 hash1 text:=encode(extensions.digest(repeat('1',64),'sha256'),'hex');
 hash2 text:=encode(extensions.digest(repeat('2',64),'sha256'),'hex');
 hash3 text:=encode(extensions.digest(repeat('3',64),'sha256'),'hex');
 old_email public.email_messages; password_before text; message uuid; before_commit bigint; sealed jsonb:='{"iv":"fixture","ciphertext":"fixture"}';
BEGIN
 PERFORM create_user_for_test('team_manager','team_manager@test.local'); manager:=get_user_id('team_manager');
 PERFORM create_user_for_test('team_member','team_member@test.local'); member:=get_user_id('team_member');
 PERFORM create_user_for_test('team_account','team_account@test.local'); account_user:=get_user_id('team_account');
 PERFORM create_user_for_test('team_other','team_other@test.local'); outsider:=get_user_id('team_other');
 UPDATE auth.users SET encrypted_password=extensions.crypt('ExistingAccountPassword123',extensions.gen_salt('bf')) WHERE id=member;
 INSERT INTO public.organizations(title,data) VALUES('Team tenant','{"APP_NAME":"Team fixture","DEFAULT_URL":"https://example.test","secret":"must-not-leak"}') RETURNING id INTO org;
 UPDATE public.user_info ui SET organization=org,email_readonly=au.email FROM auth.users au
 WHERE ui.id=au.id AND ui.id IN(manager,member,account_user,outsider);
 INSERT INTO public.units(title,organization) VALUES('Team unit',org) RETURNING id INTO unit_id;
 INSERT INTO public.unit_users(unit,"user",is_manager,is_editor) VALUES(unit_id,manager,true,true),(unit_id,member,false,false);
 INSERT INTO public.occasions(title,link,unit,organization,is_open,is_hidden,start_time,end_time) VALUES('Team event','team-fixture-'||draft_id::text,unit_id,org,false,true,now()+interval '30 days',now()+interval '31 days') RETURNING id INTO event_id;
 INSERT INTO public.occasion_setup_drafts(id,unit,organization,author,data) VALUES(draft_id,unit_id,org,manager,
  jsonb_build_object('title','Team event','sendTeamInvitations',true,'teamInviteRoles',jsonb_build_object('team_new@test.local','read_only'),'teamInviteEmails',jsonb_build_array('team_member@test.local','team_account@test.local','team_new@test.local')));
 PERFORM set_config('request.jwt.claim.sub',manager::text,true); PERFORM set_config('request.jwt.claim.role','authenticated',true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 response:=public.preview_occasion_setup_invitations(draft_id,ARRAY[' TEAM_MEMBER@test.local ','team_account@test.local','team_new@test.local','team_new@test.local']);
 PERFORM assert_eq(jsonb_array_length(response->'recipients'),3,'Invitation input normalized and deduplicated');
 PERFORM assert_eq(response#>>'{recipients,0,kind}','account','Existing tenant account classification');
 PERFORM assert_eq(response#>>'{recipients,1,kind}','member','Existing unit member classification');
 PERFORM assert_eq(response#>>'{recipients,2,kind}','new','New account classification');
 PERFORM assert_eq(response#>>'{recipients,2,role}','read_only','Preview uses selected per-recipient permission');
 PERFORM assert_true(response#>'{event,id}'='null'::jsonb,'Preview works before finalization');
 PERFORM assert_false(response->'organizationData' ? 'secret','Preview returns safe organization fields');
 BEGIN PERFORM public.enqueue_occasion_setup_invitation(draft_id,'team_member@test.local',hash1,sealed,repeat('a',64),'editor'); RAISE EXCEPTION 'Unfinalized accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 BEGIN PERFORM public.preview_occasion_setup_invitations(draft_id,ARRAY['invalid']); RAISE EXCEPTION 'Invalid email accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 BEGIN PERFORM public.preview_occasion_setup_invitations(draft_id,array_fill('x@test.local'::text,ARRAY[21])); RAISE EXCEPTION 'Too many emails accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 EXECUTE 'RESET ROLE';
 UPDATE public.occasion_setup_drafts SET data=data||jsonb_build_object('finalizedOccasion',event_id) WHERE id=draft_id;
 SELECT encrypted_password INTO password_before FROM auth.users WHERE id=member;
 EXECUTE 'SET LOCAL ROLE authenticated';
 response:=public.enqueue_occasion_setup_invitation(draft_id,' TEAM_MEMBER@test.local ',hash1,sealed,repeat('a',64),'editor');
 message:=(response->>'message_id')::uuid;
 PERFORM assert_eq(response->>'status','queued','Invitation queued');
 response:=public.enqueue_occasion_setup_invitation(draft_id,'team_member@test.local',hash3,sealed,repeat('b',64),'editor');
 PERFORM assert_eq((response->>'message_id')::uuid,message,'Retry keeps original message and token');
 PERFORM assert_true((response->>'replayed')::boolean,'Retry marked replayed');
 BEGIN PERFORM public.enqueue_occasion_setup_invitation(draft_id,'not-selected@test.local',hash3,sealed,repeat('a',64),'editor'); RAISE EXCEPTION 'Unselected email accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 BEGIN PERFORM public.enqueue_occasion_setup_invitation(draft_id,'team_new@test.local',hash2,sealed,repeat('a',64),'editor'); RAISE EXCEPTION 'Stale prepared role accepted'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 PERFORM public.enqueue_occasion_setup_invitation(draft_id,'team_new@test.local',hash2,sealed,repeat('a',64),'read_only');
 PERFORM public.enqueue_occasion_setup_invitation(draft_id,'team_account@test.local',hash3,sealed,repeat('a',64),'editor');
 EXECUTE 'RESET ROLE';
 PERFORM assert_eq((SELECT token_hash FROM public.occasion_team_invitations WHERE draft=draft_id AND email='team_member@test.local'),hash1,'Only token hash is stored');
 PERFORM assert_eq((SELECT tracking_policy FROM public.email_messages WHERE message_id=message),'disabled','Proof email tracking disabled');
 PERFORM assert_eq((SELECT encrypted_password FROM auth.users WHERE id=member),password_before,'Sending invitation never changes password');
 UPDATE public.unit_users SET is_editor=true WHERE unit=unit_id AND "user"=member;
 PERFORM set_config('request.jwt.claim.sub',member::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 response:=public.preview_occasion_setup_invitations(draft_id,ARRAY['team_account@test.local']);
 PERFORM assert_false((response->>'canManage')::boolean,'Draft editor cannot inspect tenant account existence');
 PERFORM assert_eq(jsonb_array_length(response->'recipients'),0,'Editor preview has no recipient disclosures');
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.preview_occasion_setup_invitations(draft_id,'{}'); RAISE EXCEPTION 'Non-manager preview accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.accept_occasion_team_invitation(token1); RAISE EXCEPTION 'Wrong account accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub','',true); PERFORM set_config('request.jwt.claim.role','anon',true);
 EXECUTE 'SET LOCAL ROLE anon';
 response:=public.get_occasion_team_invitation(token1);
 PERFORM assert_true((response->>'existingAccount')::boolean,'Public proof read classifies existing account');
 PERFORM assert_false(response ? 'token_hash','Public proof read never returns hash');
 PERFORM assert_eq(public.get_occasion_team_invitation(token2)->>'role','read_only','Proof view exposes selected permission');
 PERFORM assert_true(public.get_occasion_team_invitation('invalid') IS NULL,'Malformed proof has no data');
 BEGIN PERFORM public.accept_occasion_team_invitation(token1,'somePassword'); RAISE EXCEPTION 'Existing account overwritten'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.accept_occasion_team_invitation(token2,'short'); RAISE EXCEPTION 'Short password accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 response:=public.accept_occasion_team_invitation(token2,'NewUserPassword123!');
 PERFORM assert_true((response->>'newAccount')::boolean,'Invited account created with user chosen password');
 PERFORM assert_true((response->>'accepted')::boolean,'New account invitation accepted');
 BEGIN PERFORM public.accept_occasion_team_invitation(token2,'AnotherPassword123'); RAISE EXCEPTION 'Consumed token created again'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 EXECUTE 'RESET ROLE';
 SELECT id INTO new_user FROM public.user_info WHERE organization=org AND email_readonly='team_new@test.local';
 PERFORM assert_true((SELECT encrypted_password=extensions.crypt('NewUserPassword123!',encrypted_password) FROM auth.users WHERE id=new_user),'New account stores only hash of user chosen password');
 PERFORM assert_true((SELECT is_editor_view AND NOT is_editor FROM public.occasion_users WHERE occasion=event_id AND "user"=new_user),'Read-only invitation cannot edit');
 PERFORM assert_false(EXISTS(SELECT 1 FROM public.unit_users WHERE "user"=new_user),'New account gets no unit membership');
 PERFORM assert_true(EXISTS(SELECT 1 FROM public.client_commits WHERE occasion=event_id AND source='profile.team_invitation.accept'),'Acceptance published canonical audit');
 INSERT INTO public.occasion_users(occasion,"user",is_manager,is_receptionist) VALUES(event_id,member,true,true);
 PERFORM set_config('request.jwt.claim.sub',member::text,true); PERFORM set_config('request.jwt.claim.role','authenticated',true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 response:=public.accept_occasion_team_invitation(token1);
 PERFORM assert_true((response->>'accepted')::boolean,'Existing account accepts after login');
 response:=public.accept_occasion_team_invitation(token1);
 PERFORM assert_true((response->>'accepted')::boolean,'Accepted account retry is idempotent');
 BEGIN PERFORM public.reset_password_and_enqueue_email(member,'123456',event_id,sealed,repeat('a',64),'legacy-team-invite',now()+interval '10 minutes');
  RAISE EXCEPTION 'Legacy team invitation changed account password'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 EXECUTE 'RESET ROLE';
 PERFORM assert_true((SELECT is_manager AND is_receptionist AND is_editor AND is_editor_view FROM public.occasion_users WHERE occasion=event_id AND "user"=member),'Acceptance preserves broader roles');
 PERFORM assert_eq((SELECT encrypted_password FROM auth.users WHERE id=member),password_before,'Acceptance never changes existing password');
 SELECT * INTO old_email FROM public.email_messages WHERE message_id=message;
 old_email.message_kind:='sign_in'; old_email.recipient_user:=member;
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 PERFORM assert_false(public.email_intent_valid(old_email),'Old queued team passwords cannot be sent');
 response:=public.enqueue_email('custom',jsonb_build_object('organization',org,'occasion',event_id,'unit',unit_id,'recipient_user',member),
  'team_member@test.local','{}'::jsonb,'team-access-notice-fixture-'||draft_id::text,'TEAM_ACCESS_NOTICE');
 UPDATE public.email_messages SET workflow_state='accepted',accepted_at=now() WHERE message_id=(response->>'message_id')::uuid;
 PERFORM set_config('request.jwt.claim.role','authenticated',true);
 PERFORM assert_true(EXISTS(SELECT 1 FROM jsonb_array_elements(public.get_occasion_sign_in_email_statuses(event_id)) item
  WHERE item->>'user'=member::text AND (item->>'send_count')::int=1),'Accepted team access notice appears in invitation status');
 UPDATE public.occasion_team_invitations SET expires_at=now()-interval '1 second' WHERE draft=draft_id AND email='team_account@test.local';
 PERFORM set_config('request.jwt.claim.sub',account_user::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM assert_true(public.get_occasion_team_invitation(token3) IS NULL,'Expired invitation hidden');
 BEGIN PERFORM public.accept_occasion_team_invitation(token3); RAISE EXCEPTION 'Expired token accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 EXECUTE 'RESET ROLE';
 UPDATE public.occasion_team_invitations SET expires_at=now()+interval '1 day' WHERE draft=draft_id AND email='team_account@test.local';
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 PERFORM assert_true(public.email_intent_valid((SELECT m FROM public.email_messages m JOIN public.occasion_team_invitations i
  ON i.message_id=m.message_id WHERE i.draft=draft_id AND i.email='team_account@test.local')),'Pending invitation remains deliverable');
 UPDATE public.unit_users SET is_manager=false WHERE unit=unit_id AND "user"=manager;
 PERFORM assert_false(public.email_intent_valid((SELECT m FROM public.email_messages m JOIN public.occasion_team_invitations i
  ON i.message_id=m.message_id WHERE i.draft=draft_id AND i.email='team_account@test.local')),'Revoked manager invitation cannot deliver');
 PERFORM set_config('request.jwt.claim.role','authenticated',true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM assert_true(public.get_occasion_team_invitation(token3) IS NULL,'Invitation revoked when inviting manager loses permission');
 BEGIN PERFORM public.accept_occasion_team_invitation(token3); RAISE EXCEPTION 'Revoked manager token accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 EXECUTE 'RESET ROLE';
 PERFORM assert_true((SELECT count(*)=2 FROM pg_constraint c
  WHERE c.conrelid='public.occasion_team_invitations'::regclass AND c.confrelid='auth.users'::regclass
   AND c.contype='f' AND c.confdeltype='c'),'Invitation references never prevent canonical account deletion');
 PERFORM assert_false(has_table_privilege('anon','public.occasion_team_invitations','SELECT'),'Anonymous has no invitation table access');
 PERFORM assert_false(has_table_privilege('authenticated','public.occasion_team_invitations','SELECT'),'Authenticated has no invitation table access');
END $$;
